import{_ as t,o as a,c as r,ak as o}from"./chunks/framework.B8jO0odJ.js";const f=JSON.parse('{"title":"Chainy offline progress and records","description":"Game design · Data contract · Evaluation","frontmatter":{"title":"Chainy offline progress and records","description":"Game design · Data contract · Evaluation","source":"docs/offline-data-plan.md","category":"Research & evaluation","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/offline-data-plan.md","filePath":"content/docs/offline-data-plan.md"}'),n={name:"content/docs/offline-data-plan.md"};function i(s,e,c,d,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-offline-progress-and-records">Chainy offline progress and records<a class="header-anchor" href="#chainy-offline-progress-and-records" aria-label="Link to this section">​</a></h1><p><a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">Game design</a> · <a href="/Chainy-Docs/content/docs/design/database-schema.html">Data contract</a> · <a href="/Chainy-Docs/content/docs/qa-evaluation.html">Evaluation</a></p><p><strong>Documentation and preparation only until the owner&#39;s explicit FINAL approval.</strong> This plan defines local behavior and record meanings; it does not authorize implementation, a database change, or collection of participant data.</p><h2 id="offline-play">Offline play<a class="header-anchor" href="#offline-play" aria-label="Link to this section">​</a></h2><p>The complete game runs on one Android device without a sign-in server or network request. SQLite stores isolated profile progress across Web3 → Blockchain → AI. Each world has 13 ordered lesson entries, three distinct minigames, and a required 13-question review with one question per lesson. AI activities use labeled authored simulations, without a hosted model or actual training requirement. Local profile identifiers do not authenticate a learner or recover data from another phone.</p><p>The <a href="/Chainy-Docs/content/docs/design/database-schema.html#current-progress-contract">data contract</a> is the single reference for persisted fields and atomic transitions. Tutorial progress and completed item/NPC prerequisites survive restart. Lesson completion, encyclopedia entry, and next objective save together. World completion requires all 13 entries and a saved review in which all 13 questions have been answered correctly.</p><h2 id="what-records-mean">What records mean<a class="header-anchor" href="#what-records-mean" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Record</th><th>Meaning and limit</th></tr></thead><tbody><tr><td>Recorded entry</td><td>A lesson&#39;s collection or activity rule completed and saved; not proof that its explanation was understood</td></tr><tr><td>First response</td><td>The first submitted choice for a question in an identified attempt; later corrections do not overwrite it</td></tr><tr><td>Corrected completion</td><td>Every review item eventually answered correctly with feedback/retries; distinct from a first-response score</td></tr><tr><td>Abandoned attempt</td><td>Partial responses retained after leaving or losing the session; not a completed score</td></tr><tr><td>Replay</td><td>A new attempt; never removes an earlier world completion or creates a second collection entry</td></tr></tbody></table><p>A completed attempt reports first responses as X/13 separately from completion after correction. An unfinished review restarts all 13 questions in a new attempt on return. Preserve its previous partial responses as abandoned. Neither replay nor corrected completion establishes independent learning gain, a school grade, or validated assessment performance.</p><h2 id="local-recovery-and-privacy">Local recovery and privacy<a class="header-anchor" href="#local-recovery-and-privacy" aria-label="Link to this section">​</a></h2><p>Save before showing a new entry, objective, completed world, or unlock. A failed write leaves the prior checkpoint available and offers retry. Minigame Exit preserves prerequisites without granting completion; an unfinished round restarts on re-entry. Profile changes clear prior in-memory progress and reject stale results. Unknown schema/content versions or damaged records are preserved with recovery feedback. Compatible app updates must preserve existing supported saves.</p><p>Use synthetic profiles for technical verification. Keep participant identities, identity maps, identifiable photographs, credentials, and signing keys out of repositories and issues. Any real evaluation records need a separately documented purpose, approved fields, custodian, access, retention, and actual permission evidence. Local storage alone does not establish those permissions or make records anonymous.</p><h2 id="scope-and-evidence">Scope and evidence<a class="header-anchor" href="#scope-and-evidence" aria-label="Link to this section">​</a></h2><p>Teacher enrollment, vouchers, pairing, dashboards, exports, transfer/upload services, and automatic content distribution are outside the current game. They are preserved only in the <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/offline-data-plan.html">historical offline service plan</a>. No networking backend or teacher tooling is needed for the specified learning journey. An APK update is a separate release action, with its own build identity and save-compatibility check.</p><p>The <a href="/Chainy-Docs/content/docs/project-baseline.html#current-implementation-evidence">November 11 audit</a> found existing storage and profile infrastructure, not a verified implementation of this new contract. Android toolchain and reference-device acceptance remain unverified. The November 10 community session&#39;s actual outcome is also unverified; do not label it accepted gameplay or school pilot evidence without records. Keep integration, device QA, manuscript evidence, and rehearsal time before the November 21, 2026 pre-final.</p></div>',1)])])}const m=t(n,[["render",i]]);export{f as __pageData,m as default};
